test('createInvoice: gold customer tier discount with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 10 * 8500 + 5 * 9500;
  const expectedDiscount = Math.round(expectedSubtotal * 5 / 100);
  assert.strictEqual(totals.subtotal, expectedSubtotal);
  assert.strictEqual(totals.discount, expectedDiscount);
});

